import React, { Component } from "react";
import "./Login.css";

export default class Login extends Component {
    render() {
        const pagesdata=PagesJson.find(item => item.pageId === 4);
        const buttonsdata=pagesdata.buttons; 
        const button1Text = buttonsdata.find(btn => btn.p1).p1;
        const button2Text = buttonsdata.find(btn => btn.p2).p2;
        return (

            <div className="content-container ">
                <div className="formbox">
                   <div className="button-box1">
                     <div id="btn1"></div>
                        <button type="button" className="toggle-btn">button1Text</button>
                        <button type="button" className="toggle-btn">Sign Up</button> 
                    </div>


                <form className="input-group">
                    <input type="text" className="input-field" placeholder="Email" required/>
                    <input type="password" className="input-field" placeholder="Password" required/>
                    <a href="#" className="forget">Forget/Change your password?</a>
                <button type="submit" className="submit-btn">Log in</button>
                </form>
              </div>
            </div>
        );
    }
}
